package com.ampyai.core;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

/**
 * FRAP v0: tiny bounded vector language. No loops, Android reflection, file
 * access, network access, arbitrary Java, or generated bytecode.
 */
public final class FrapEngine {
    public static final class Shape {
        public final String op;
        public final float[] args;
        Shape(String op,float... args){this.op=op;this.args=args;}
    }
    public static final class Program {
        public final List<Shape> shapes;
        Program(List<Shape> shapes){this.shapes=shapes;}
        public String toSvg() {
            StringBuilder s=new StringBuilder(
                "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 1000 1000\">"+
                "<rect width=\"1000\" height=\"1000\" fill=\"#101c29\"/>");
            for(Shape v:shapes) {
                float[] a=v.args;
                switch(v.op){
                    case "line":
                        s.append(String.format(Locale.US,
                            "<line x1=\"%.1f\" y1=\"%.1f\" x2=\"%.1f\" y2=\"%.1f\" stroke=\"#79eac5\" stroke-width=\"5\"/>",
                            a[0]*1000,a[1]*1000,a[2]*1000,a[3]*1000));break;
                    case "circle":
                        s.append(String.format(Locale.US,
                            "<circle cx=\"%.1f\" cy=\"%.1f\" r=\"%.1f\" stroke=\"#79eac5\" stroke-width=\"5\" fill=\"none\"/>",
                            a[0]*1000,a[1]*1000,a[2]*1000));break;
                    case "rect":
                        s.append(String.format(Locale.US,
                            "<rect x=\"%.1f\" y=\"%.1f\" width=\"%.1f\" height=\"%.1f\" stroke=\"#79eac5\" stroke-width=\"5\" fill=\"none\"/>",
                            a[0]*1000,a[1]*1000,a[2]*1000,a[3]*1000));break;
                }
            }
            return s.append("</svg>").toString();
        }
    }
    public static Program parse(String source) {
        if(source==null || source.length()>5000)
            throw new IllegalArgumentException("FRAP: massimo 5000 caratteri.");
        String[] lines=source.split("\\r?\\n");
        List<Shape> shapes=new ArrayList<>();
        for(int row=0;row<lines.length;row++){
            String line=lines[row].trim().toLowerCase(Locale.ROOT);
            if(line.isEmpty()||line.startsWith("#"))continue;
            String[] parts=line.split("\\s+");
            String op=parts[0];
            int need=op.equals("circle")?3:
                    (op.equals("line")||op.equals("rect"))?4:-1;
            if(need<0||parts.length!=need+1)
                throw new IllegalArgumentException("FRAP riga "+(row+1)+
                    ": usa line x1 y1 x2 y2, rect x y w h, circle cx cy r");
            float[] values=new float[need];
            for(int j=0;j<need;j++) {
                try { values[j]=Float.parseFloat(parts[j+1]);}
                catch(NumberFormatException ex){
                    throw new IllegalArgumentException("FRAP riga "+(row+1)+": numero non valido.");
                }
                if(!Float.isFinite(values[j])||values[j]<0||values[j]>1)
                    throw new IllegalArgumentException("FRAP: coordinate tra 0 e 1.");
            }
            if((op.equals("circle") && values[2]==0)||
               (op.equals("rect")&&(values[2]==0||values[3]==0)))
                throw new IllegalArgumentException("FRAP: dimensioni positive richieste.");
            if(op.equals("rect") && (values[0]+values[2]>1||values[1]+values[3]>1))
                throw new IllegalArgumentException("FRAP: rettangolo oltre il canvas.");
            if(op.equals("circle") &&
                    (values[0]-values[2]<0||values[1]-values[2]<0||
                     values[0]+values[2]>1||values[1]+values[2]>1))
                throw new IllegalArgumentException("FRAP: cerchio oltre il canvas.");
            shapes.add(new Shape(op,values));
            if(shapes.size()>100)throw new IllegalArgumentException("FRAP: massimo 100 istruzioni.");
        }
        if(shapes.isEmpty())throw new IllegalArgumentException("FRAP: programma vuoto.");
        return new Program(shapes);
    }
    private FrapEngine(){}
}
